-- PR 5: selection validation, primary address retention, and profile-channel synchronization.
begin;

create or replace function public.customer_merge_validate_resolutions(p_business_id uuid,p_primary_customer_id uuid,p_duplicate_customer_id uuid,p_resolutions jsonb)
returns void language plpgsql security definer set search_path=public as $$
declare selected_address uuid;
begin
 if jsonb_typeof(coalesce(p_resolutions,'{}'::jsonb)) <> 'object' then raise exception 'CUSTOMER_MERGE_INVALID_RESOLUTIONS' using errcode='22023'; end if;
 selected_address:=nullif(p_resolutions->>'primaryAddressId','')::uuid;
 if selected_address is not null and not exists(select 1 from public.customer_addresses where id=selected_address and business_id=p_business_id and customer_id in(p_primary_customer_id,p_duplicate_customer_id) and is_active) then
  raise exception 'CUSTOMER_MERGE_INVALID_ADDRESS_SELECTION' using errcode='22023';
 end if;
 if nullif(p_resolutions->>'email','') is not null and not exists(select 1 from public.customer_contact_channels where business_id=p_business_id and customer_id in(p_primary_customer_id,p_duplicate_customer_id) and channel_type='email' and normalized_value=lower(btrim(p_resolutions->>'email')) and is_active) then raise exception 'CUSTOMER_MERGE_INVALID_EMAIL_SELECTION' using errcode='22023'; end if;
 if nullif(p_resolutions->>'phone','') is not null and not exists(select 1 from public.customer_contact_channels where business_id=p_business_id and customer_id in(p_primary_customer_id,p_duplicate_customer_id) and channel_type='phone' and normalized_value=public.normalize_phone_e164(p_resolutions->>'phone') and is_active) then raise exception 'CUSTOMER_MERGE_INVALID_PHONE_SELECTION' using errcode='22023'; end if;
end $$;
revoke all on function public.customer_merge_validate_resolutions(uuid,uuid,uuid,jsonb) from public;

create or replace function public.customer_merge_preview(p_primary_customer_id uuid,p_duplicate_customer_id uuid,p_resolutions jsonb default '{}'::jsonb)
returns jsonb language plpgsql security definer set search_path=public as $$
declare b uuid;p public.customers%rowtype;d public.customers%rowtype;blockers jsonb;state jsonb;request_fp text;preview_fp text;
begin
 select x.business_id into b from public.customer_merge_assert_authorized_pair(p_primary_customer_id,p_duplicate_customer_id) x;
 select (x.primary_customer).* into p from public.customer_merge_assert_authorized_pair(p_primary_customer_id,p_duplicate_customer_id) x;
 select (x.duplicate_customer).* into d from public.customer_merge_assert_authorized_pair(p_primary_customer_id,p_duplicate_customer_id) x;
 perform public.customer_merge_validate_resolutions(b,p.id,d.id,p_resolutions);
 blockers:=public.customer_merge_billing_blockers(b,p.id,d.id);
 state:=jsonb_build_object('primary',to_jsonb(p),'duplicate',to_jsonb(d),'resolutions',p_resolutions,
  'channels',(select coalesce(jsonb_agg(to_jsonb(x) order by x.channel_type,x.normalized_value),'[]'::jsonb) from public.customer_contact_channels x where x.business_id=b and x.customer_id in(p.id,d.id) and x.is_active),
  'addresses',(select coalesce(jsonb_agg(to_jsonb(x) order by x.created_at,x.id),'[]'::jsonb) from public.customer_addresses x where x.business_id=b and x.customer_id in(p.id,d.id) and x.is_active),
  'counts',jsonb_build_object('activeJobs',(select count(*) from public.jobs x where x.business_id=b and x.customer_id=d.id and not x.is_deleted and x.status not in('completed','canceled','declined')),'historicalJobs',(select count(*) from public.jobs x where x.business_id=b and x.customer_id=d.id and (x.is_deleted or x.status in('completed','canceled','declined'))),'bookings',(select count(*) from public.bookings x where x.business_id=b and x.customer_id=d.id),'estimates',(select count(*) from public.estimates x where x.business_id=b and x.customer_id=d.id and not x.is_deleted),'locations',(select count(*) from public.service_locations x where x.business_id=b and x.customer_id=d.id and not x.is_deleted),'servicePlans',(select count(*) from public.recurring_service_series x where x.business_id=b and x.customer_id=d.id),'invoices',(select count(*) from public.invoices x where x.business_id=b and x.customer_id=d.id and not x.is_deleted),'payments',(select count(*) from public.payments x where x.business_id=b and x.customer_id=d.id),'messages',(select count(*) from public.customer_messages x where x.business_id=b and x.customer_id=d.id)),'billingBlockers',blockers);
 request_fp:=public.customer_merge_request_fingerprint(p.id,d.id,p_resolutions); preview_fp:=encode(extensions.digest(state::text,'sha256'),'hex');
 return jsonb_build_object('primaryCustomer',to_jsonb(p),'duplicateCustomer',to_jsonb(d),'proposedProfile',jsonb_build_object('first_name',coalesce(p_resolutions->>'firstName',p.first_name),'last_name',coalesce(p_resolutions->>'lastName',p.last_name),'company_name',coalesce(p_resolutions->>'companyName',p.company_name),'email',coalesce(p_resolutions->>'email',p.email),'phone',coalesce(p_resolutions->>'phone',p.phone),'primary_address_id',nullif(p_resolutions->>'primaryAddressId','')),'alternateChannels',state->'channels','addressCandidates',state->'addresses','dependencyCounts',state->'counts','billing',jsonb_build_object('compatible',jsonb_array_length(blockers)=0,'blockers',blockers),'blockers',blockers,'warnings',case when jsonb_array_length(blockers)=0 then '[]'::jsonb else jsonb_build_array(jsonb_build_object('code','CUSTOMER_MERGE_BILLING_REVIEW','message','Historical financial records remain unchanged; active billing dependencies block this merge.')) end,'requestFingerprint',request_fp,'previewFingerprint',preview_fp);
end $$;

-- The existing engine performs all reassignment before this profile update. This
-- wrapper is intentionally replaced in full so the address selection is inside
-- its transaction and therefore protected by the same stale-preview hash.
create or replace function public.confirm_customer_merge(p_primary_customer_id uuid,p_duplicate_customer_id uuid,p_resolutions jsonb,p_preview_fingerprint text,p_idempotency_key uuid)
returns jsonb language plpgsql security definer set search_path=public as $$
declare b uuid;p public.customers%rowtype;d public.customers%rowtype;preview jsonb;request_fp text;existing public.customer_merge_audits%rowtype;blockers jsonb;counts jsonb;audit_id uuid;selected_address uuid;
begin
 request_fp:=public.customer_merge_request_fingerprint(p_primary_customer_id,p_duplicate_customer_id,coalesce(p_resolutions,'{}'::jsonb)); select * into existing from public.customer_merge_audits where idempotency_key=p_idempotency_key;
 if found then if existing.request_fingerprint<>request_fp then raise exception 'CUSTOMER_MERGE_IDEMPOTENCY_CONFLICT' using errcode='23505'; end if; if not public.has_business_role(existing.business_id,array['owner','admin']) then raise exception 'CUSTOMER_MERGE_FORBIDDEN' using errcode='42501'; end if; return jsonb_build_object('status','completed','auditId',existing.id,'primaryCustomerId',existing.primary_customer_id,'duplicateCustomerId',existing.duplicate_customer_id,'idempotent',true,'affectedRecordCounts',existing.affected_record_counts); end if;
 perform pg_advisory_xact_lock(hashtextextended(least(p_primary_customer_id,p_duplicate_customer_id)::text||':'||greatest(p_primary_customer_id,p_duplicate_customer_id)::text,481516)); select * into p from public.customers where id=p_primary_customer_id for update; select * into d from public.customers where id=p_duplicate_customer_id for update; select x.business_id into b from public.customer_merge_assert_authorized_pair(p_primary_customer_id,p_duplicate_customer_id) x; select (x.primary_customer).* into p from public.customer_merge_assert_authorized_pair(p_primary_customer_id,p_duplicate_customer_id) x; select (x.duplicate_customer).* into d from public.customer_merge_assert_authorized_pair(p_primary_customer_id,p_duplicate_customer_id) x; preview:=public.customer_merge_preview(p.id,d.id,coalesce(p_resolutions,'{}'::jsonb)); if preview->>'previewFingerprint'<>p_preview_fingerprint then raise exception 'CUSTOMER_MERGE_STALE_PREVIEW' using errcode='40001'; end if; blockers:=preview->'blockers';if jsonb_array_length(blockers)>0 then raise exception 'CUSTOMER_MERGE_BLOCKED: %',blockers using errcode='55000'; end if;
 update public.service_locations set customer_id=p.id,updated_at=now(),updated_by=auth.uid(),is_primary=false where business_id=b and customer_id=d.id; update public.recurring_service_series set customer_id=p.id,updated_at=now(),updated_by=auth.uid() where business_id=b and customer_id=d.id; update public.jobs set customer_id=p.id,updated_at=now(),updated_by=auth.uid() where business_id=b and customer_id=d.id and not is_deleted and status not in('completed','canceled','declined'); update public.estimates set customer_id=p.id,updated_at=now(),updated_by=auth.uid() where business_id=b and customer_id=d.id and not is_deleted and status in('draft','sent','viewed'); update public.customer_addresses set customer_id=p.id,is_primary=false,updated_at=now(),updated_by=auth.uid() where business_id=b and customer_id=d.id; update public.customer_external_references set customer_id=p.id where business_id=b and customer_id=d.id; update public.customer_hvac_equipment set customer_id=p.id,updated_at=now(),updated_by=auth.uid() where business_id=b and customer_id=d.id; update public.customer_employee_preferences set customer_id=p.id where business_id=b and customer_id=d.id; update public.customer_messages set customer_id=p.id,updated_at=now() where business_id=b and customer_id=d.id; update public.inbound_sms_messages set customer_id=p.id where business_id=b and customer_id=d.id; update public.missed_call_recovery_leads set customer_id=p.id,updated_at=now() where business_id=b and customer_id=d.id; update public.missed_call_recovery_messages set customer_id=p.id where business_id=b and customer_id=d.id;
 update public.customer_contact_channels set is_primary=false,updated_at=now(),updated_by=auth.uid() where business_id=b and customer_id=d.id; update public.customer_contact_channels pc set consent_status='opted_out',consent_recorded_at=coalesce(pc.consent_recorded_at,dc.consent_recorded_at),updated_at=now(),updated_by=auth.uid() from public.customer_contact_channels dc where pc.business_id=b and dc.business_id=b and pc.customer_id=p.id and dc.customer_id=d.id and pc.channel_type=dc.channel_type and pc.normalized_value=dc.normalized_value and dc.consent_status in('opted_out','unsubscribed'); update public.customer_contact_channels dc set customer_id=p.id,updated_at=now(),updated_by=auth.uid() where dc.business_id=b and dc.customer_id=d.id and not exists(select 1 from public.customer_contact_channels pc where pc.business_id=b and pc.customer_id=p.id and pc.channel_type=dc.channel_type and pc.normalized_value=dc.normalized_value);
 update public.customers set email=null,updated_at=now(),updated_by=auth.uid() where id=d.id and nullif(lower(p_resolutions->>'email'),'')=lower(email) and lower(email)<>lower(p.email); update public.customers set first_name=coalesce(nullif(p_resolutions->>'firstName',''),first_name),last_name=coalesce(nullif(p_resolutions->>'lastName',''),last_name),company_name=coalesce(nullif(p_resolutions->>'companyName',''),company_name),email=coalesce(nullif(lower(p_resolutions->>'email'),''),email),phone=coalesce(nullif(p_resolutions->>'phone',''),phone),notes=concat_ws(E'\n\n',nullif(notes,''),nullif(d.notes,'')),tags=coalesce((select array_agg(distinct x) from unnest(coalesce(tags,'{}')||coalesce(d.tags,'{}')) x),'{}'::text[]),updated_at=now(),updated_by=auth.uid() where id=p.id;
 selected_address:=nullif(p_resolutions->>'primaryAddressId','')::uuid; if selected_address is not null then update public.customer_addresses set is_primary=(id=selected_address),updated_at=now(),updated_by=auth.uid() where business_id=b and customer_id=p.id and is_active; end if;
 update public.customers set is_active=false,is_deleted=true,merged_into_customer_id=p.id,merged_at=now(),merged_by=auth.uid(),updated_at=now(),updated_by=auth.uid() where id=d.id; counts:=preview->'dependencyCounts'; insert into public.customer_merge_audits(business_id,primary_customer_id,duplicate_customer_id,performed_by,idempotency_key,request_fingerprint,preview_fingerprint,request_payload,primary_snapshot,duplicate_snapshot,field_resolutions,affected_record_counts,status,completed_at) values(b,p.id,d.id,auth.uid(),p_idempotency_key,request_fp,p_preview_fingerprint,jsonb_build_object('primaryCustomerId',p.id,'duplicateCustomerId',d.id),to_jsonb(p),to_jsonb(d),coalesce(p_resolutions,'{}'::jsonb),counts,'completed',now()) returning id into audit_id; insert into public.business_activity(business_id,actor_user_id,action,entity_type,entity_id,summary) values(b,auth.uid(),'customer_merged','customer',p.id,concat_ws(' ',coalesce(d.first_name,''),coalesce(d.last_name,''),'was merged into this customer profile'));
 return jsonb_build_object('status','completed','auditId',audit_id,'primaryCustomerId',p.id,'duplicateCustomerId',d.id,'idempotent',false,'affectedRecordCounts',counts);
end $$;
revoke all on function public.confirm_customer_merge(uuid,uuid,jsonb,text,uuid) from public;
grant execute on function public.confirm_customer_merge(uuid,uuid,jsonb,text,uuid) to authenticated;
notify pgrst,'reload schema';
commit;
